//! Test utilities for seismic provider
use alloy_primitives::{hex, Bytes};
use alloy_sol_types::sol;

// Test contract interface
sol! {

    interface ISeismicCounter {
        event setNumberEmit();
        event incrementEmit();
        function setNumber(suint256 newNumber) public;
        function increment() public;
        function isOdd() public view returns (bool);
    }

}

// EncryptedLogs contract — exercises RNG + AES precompiles
// Source: seismic-solidity/test/seismic_example/encrypted_logs.sol
sol! {
    #[derive(Debug, PartialEq)]
    #[sol(rpc, bytecode = "")]
    contract EncryptedLogs {
        event EncryptedMessage(uint96 indexed nonce, bytes ciphertext);
        function setAESKey(suint256 key) external;
        function submitMessage(bytes calldata message) external;
        function decrypt(uint96 nonce, bytes calldata ciphertext)
            external
            view
            returns (bytes memory plaintext);
    }
}

/// Deployment bytecode for a minimal RNG caller contract.
/// On any call, STATICCALLs the RNG precompile (0x64) requesting 32 random bytes,
/// stores the result in slot 0, increments a call counter in slot 1, and returns the result.
pub fn get_rng_caller_deploy_bytecode() -> Bytes {
    Bytes::from_static(&hex!(
        "602d600c600039602d6000f3"
        "6300000020600052602060006004601c60645afa50600051806000556001546001016001556000526020"
        "6000f3"
    ))
}

