// FlaggedStorage test contract — public + private storage slots.
// Source: uint256 public publicSlot (slot 0), suint256 private privateSlot (slot 1)
sol! {
    #[sol(rpc, bytecode = "")]
    contract FlaggedStorageTest {
        function setPublic(uint256 value) external;
        function setPrivate(suint256 value) external;
        function readPublicSload() external view returns (uint256);
        function readPrivateSloadRaw() external view returns (uint256);
        function readPrivateCload() external view returns (uint256);
        function readPublicCload() external view returns (uint256);
        function readPrivateSload() external view returns (uint256);
    }
}
